-- Delete only the authenticated recipient's own notification.
create or replace function public.notification_delete(p_notification_id uuid) returns jsonb language plpgsql security definer set search_path='public' as $$ declare removed integer; begin if auth.uid() is null then raise exception 'authentication required'; end if; delete from public.notifications where id=p_notification_id and recipient_user_id=auth.uid(); get diagnostics removed=row_count; if removed=0 then raise exception 'notification not found'; end if; return jsonb_build_object('ok',true,'deleted',true); end $$; revoke all on function public.notification_delete(uuid) from public,anon; grant execute on function public.notification_delete(uuid) to authenticated;
